#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cstdlib>
#include <utility>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, p;
    cin >> n >> p;
    vector<pair<int, int>> post(p);
    for (auto &[x, y] : post) cin >> x >> y;
    constexpr int width = 1001;
    vector<long long> offset(width * width, -1);
    long long perimeter = 0;
    for (int i = 0; i < p; ++i) {
        auto [x, y] = post[i];
        auto [xx, yy] = post[(i + 1) % p];
        int dx = (xx > x) - (xx < x);
        int dy = (yy > y) - (yy < y);
        int length = abs(xx - x) + abs(yy - y);
        for (int k = 0; k < length; ++k) {
            int key = (x + k * dx) * width + y + k * dy;
            offset[key] = perimeter + k;
        }
        perimeter += length;
    }
    while (n--) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        long long difference = llabs(offset[x1 * width + y1] - offset[x2 * width + y2]);
        cout << min(difference, perimeter - difference) << '\n';
    }
}
