**7. Original C++17 implementation.** All hints are read before reconstruction, including when the result is impossible.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cstdlib>
#include <utility>
using namespace std;
vector<int> reconstruct(const vector<int> &hint) {
    int n = static_cast<int>(hint.size()) + 1;
    vector<bool> present(n + 1), used(n + 1);
    for (int x : hint) present[x] = true;
    vector<int> endpoint;
    for (int x = 1; x <= n; ++x) if (!present[x]) endpoint.push_back(x);
    if (endpoint.size() == 1) endpoint.push_back(1);
    if (endpoint.size() != 2 || endpoint[0] == endpoint[1]) return {};
    sort(endpoint.begin(), endpoint.end());
    vector<int> answer(n);
    answer.front() = endpoint[0];
    answer.back() = endpoint[1];
    used[endpoint[0]] = used[endpoint[1]] = true;
    int left = 0, right = n - 1, count = 2;
    for (int x : hint) {
        int position = answer[left] > answer[right] ? ++left : --right;
        if (answer[position] != 0) {
            if (answer[position] != x) return {};
        } else {
            if (used[x]) return {};
            answer[position] = x;
            used[x] = true;
            ++count;
        }
    }
    return count == n ? answer : vector<int>{};
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> hint(n - 1);
        for (int &x : hint) cin >> x;
        auto answer = reconstruct(hint);
        if (answer.empty()) cout << -1;
        else for (int i = 0; i < n; ++i) cout << (i ? " " : "") << answer[i];
        cout << '\n';
    }
}
